(() => {
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const get=p=>window.CHARACTER_ART?.records[p.id]||[];
 function thumb(p){const a=get(p)[0];return a?`<img class="character-thumb" src="${esc(a.thumb||a.src)}" alt="${esc(p.name)}的官方立绘" loading="lazy" decoding="async" width="160" height="190">`:`<span class="art-initial" aria-hidden="true">${esc(p.name[0])}</span>`;}
 function render(p){const a=get(p);if(!a.length)return `<div class="art-missing"><span>${esc(p.name[0])}</span><p>尚未收录可核实的公开立绘</p></div>`;return `<figure class="character-illustration"><div class="art-grid" aria-hidden="true"></div><button class="art-zoom" data-open-art aria-label="放大${esc(p.name)}的立绘"><img src="${esc(a[0].src)}" alt="${esc(p.name)} · ${esc(a[0].label)}" width="700" height="1000" decoding="async"></button><figcaption><div class="art-variants" aria-label="立绘版本">${a.map((v,i)=>`<button data-art-src="${esc(v.src)}" data-art-label="${esc(v.label)}" data-art-source="${esc(v.source)}" class="${i===0?'selected':''}" aria-pressed="${i===0}">${esc(v.label)}</button>`).join('')}</div><span>官方角色美术 · <a class="art-source" href="${esc(a[0].source)}" target="_blank" rel="noopener noreferrer">资源出处 ↗</a></span><small>立绘展示不作为事件发生时间的证据</small></figcaption></figure>`;}
 const dialog=document.createElement('dialog');dialog.id='art-dialog';dialog.setAttribute('aria-label','人物立绘大图');dialog.innerHTML='<button class="art-dialog-close" aria-label="关闭立绘">关闭 ×</button><img alt=""><p></p>';document.body.append(dialog);
 document.addEventListener('click',e=>{const v=e.target.closest('[data-art-src]');if(v){const f=v.closest('figure'),im=f.querySelector('img');im.src=v.dataset.artSrc;im.alt=im.alt.split(' · ')[0]+' · '+v.dataset.artLabel;f.querySelector('.art-source').href=v.dataset.artSource;f.querySelectorAll('[data-art-src]').forEach(b=>{b.classList.toggle('selected',b===v);b.setAttribute('aria-pressed',b===v);});}const b=e.target.closest('[data-open-art]');if(b){const im=b.querySelector('img');dialog.querySelector('img').src=im.src;dialog.querySelector('img').alt=im.alt;dialog.querySelector('p').textContent=im.alt+' · 官方美术';dialog.showModal();}if(e.target.closest('.art-dialog-close')||e.target===dialog)dialog.close();});
 document.addEventListener('error',e=>{const im=e.target;if(im.tagName==='IMG'&&(im.classList.contains('character-thumb')||im.closest('.character-illustration'))){const box=document.createElement('span');box.className='art-load-error';box.textContent='图片暂未载入';im.replaceWith(box);}},true);
 window.ART_UI={get,thumb,render};
})();
